begin;
select plan(16);
select set_config('request.jwt.claims', '{"sub":"00000000-0000-0000-0000-000000000001","role":"authenticated"}', true);
set local role authenticated;
insert into public.events (id, group_id, title, starts_at, ends_at, status, created_by)
values ('90000000-0000-0000-0000-000000000099', '10000000-0000-0000-0000-000000000001', 'Poll test', now() + interval '1 day', now() + interval '2 days', 'published', auth.uid());
select lives_ok($$select public.create_poll('90000000-0000-0000-0000-000000000099', 'Question', array['A','B'], false, now() + interval '1 day')$$, 'member creates poll');
select throws_ok($$select public.create_poll('90000000-0000-0000-0000-000000000099', 'Question', array['A'], false, now() + interval '1 day')$$, '22023', null, 'requires two options');
select lives_ok($$select public.cast_vote((select id from public.polls where event_id = '90000000-0000-0000-0000-000000000099'), array[(select id from public.poll_options where label = 'A' and poll_id = (select id from public.polls where event_id = '90000000-0000-0000-0000-000000000099'))])$$, 'member votes');
select lives_ok($$select public.cast_vote((select id from public.polls where event_id = '90000000-0000-0000-0000-000000000099'), array[(select id from public.poll_options where label = 'B' and poll_id = (select id from public.polls where event_id = '90000000-0000-0000-0000-000000000099'))])$$, 'member changes vote');
select is((select count(*) from public.poll_votes where poll_id = (select id from public.polls where event_id = '90000000-0000-0000-0000-000000000099')), 1::bigint, 'one vote remains');
select throws_ok($$insert into public.poll_votes(group_id,poll_id,option_id,user_id) select group_id,poll_id,id,auth.uid() from public.poll_options where label = 'A' limit 1$$, '42501', null, 'direct votes are forbidden');
select throws_ok($$select public.cast_vote((select id from public.polls where event_id = '90000000-0000-0000-0000-000000000099'), array(select id from public.poll_options where poll_id = (select id from public.polls where event_id = '90000000-0000-0000-0000-000000000099')) )$$, '22023', null, 'single choice cannot select two options');
select set_config('request.jwt.claims', '{"sub":"00000000-0000-0000-0000-000000000003","role":"authenticated"}', true);
select throws_ok($$select public.close_poll((select id from public.polls where event_id = '90000000-0000-0000-0000-000000000099'))$$, '42501', null, 'ordinary member cannot close another member poll');
select set_config('request.jwt.claims', '{"sub":"00000000-0000-0000-0000-000000000099","role":"authenticated"}', true);
select throws_ok($$select public.create_activity_proposal('90000000-0000-0000-0000-000000000099', 'Idea', '')$$, '42501', null, 'outsider cannot propose');
select throws_ok($$select public.close_poll((select id from public.polls where event_id = '90000000-0000-0000-0000-000000000099'))$$, '42501', null, 'outsider cannot close poll');
select set_config('request.jwt.claims', '{"sub":"00000000-0000-0000-0000-000000000001","role":"authenticated"}', true);
select lives_ok($$select public.close_poll((select id from public.polls where event_id = '90000000-0000-0000-0000-000000000099'))$$, 'creator closes poll');
select throws_ok($$select public.cast_vote((select id from public.polls where event_id = '90000000-0000-0000-0000-000000000099'), array[(select id from public.poll_options where label = 'A' and poll_id = (select id from public.polls where event_id = '90000000-0000-0000-0000-000000000099'))])$$, '55000', null, 'cannot vote after close');
reset role;
update public.events set status = 'cancelled' where id = '90000000-0000-0000-0000-000000000099';
set local role authenticated;
select throws_ok($$select public.create_activity_proposal('90000000-0000-0000-0000-000000000099', 'Idea', '')$$, '55000', null, 'cannot propose to cancelled event');
select throws_ok($$select public.create_poll('90000000-0000-0000-0000-000000000099', 'Question', array['A','B'], false, now() + interval '1 day')$$, '55000', null, 'cannot create poll for cancelled event');
reset role;
update public.events set status = 'finished' where id = '90000000-0000-0000-0000-000000000099';
set local role authenticated;
select throws_ok($$select public.create_activity_proposal('90000000-0000-0000-0000-000000000099', 'Idea', '')$$, '55000', null, 'cannot propose to finished event');
select throws_ok($$select public.create_poll('90000000-0000-0000-0000-000000000099', 'Question', array['A','B'], false, now() + interval '1 day')$$, '55000', null, 'cannot create poll for finished event');
set constraints all immediate;
select * from finish();
rollback;
